#nullable enable // autogenerated

using MVZ2.GameContent.Effects;
using MVZ2.Vanilla.Audios;
using MVZ2.Vanilla.Effects;
using MVZ2Logic.Entities;
using MVZ2Logic.Level;
using PVZEngine.Callbacks;
using PVZEngine.Damages;
using PVZEngine.Definitions;
using PVZEngine.Entities;
using PVZEngine.Tools;

namespace MVZ2.GameContent.Enemies
{
    [AutoEntityBehaviourDefinition(VanillaEnemyNames.creaking)]
    public class Creaking : EntityBehaviourDefinition
    {
        public Creaking(string nsp, string name) : base(nsp, name)
        {
        }
        public override void Init(Entity entity)
        {
            base.Init(entity);
            entity.PlaySound(VanillaSoundID.creakingActivate);
        }
        public override void Update(Entity entity)
        {
            base.Update(entity);
            if (entity.Level.IsAllEnemiesCleared())
            {
                Disappear(entity);
            }
        }
        public static void Disappear(Entity entity)
        {
            entity.GetOrCreateFragment()?.Let(e =>
            {
                Fragment.AddEmitSpeed(e, 500);
            });
            entity.PlayDeathSound();
            entity.Remove();
        }
        public override void PreTakeDamage(DamageInput input, CallbackResult<bool> result)
        {
            base.PreTakeDamage(input, result);
            var entity = input.Entity;
            if (input.Source is EntitySourceReference entitySource)
            {
                var sourceEntity = entitySource.GetEntity(entity.Level);
                if (sourceEntity != null)
                {
                    if (sourceEntity == entity)
                    {
                        return;
                    }
                    else if (sourceEntity.Type == EntityTypes.CART)
                    {
                        return;
                    }
                }
            }
            result.SetFinalValue(false);
        }
    }
}
